include(joinpath(@__DIR__, "day.jl"))
function run_integrated(input)
cfg=input.config
enabled=cfg.learning=="full"
@assert cfg.learning in ("off","full") && cfg.food in ("finite","renewable")
r=lw_day(input.scene,input.clock;days=Int(cfg.days),mb_chunks=get(cfg,:mb_chunks,"off")=="on",mb_simulation=get(cfg,:mb_simulation,"off")=="on",body_purpose=get(cfg,:body_purpose,"off")=="on",general_landmarks=get(cfg,:general_landmarks,"off")=="on",choice_seed=Int(cfg.seed),digestion_mode=get(cfg,:digestion,"off"),adaptive_approach=get(cfg,:adaptive_approach,"off")=="on",continuous_descent=get(cfg,:continuous_descent,"off")=="on",rho_profile=get(cfg,:rho_profile,"off"),rho_opening_candidates_enabled=get(cfg,:rho_openings,"on")=="on",repetition_pressure=get(cfg,:repetition_pressure,"off")=="on",parent_breadth=get(cfg,:parent_breadth,"off")=="on",lateral_side=get(cfg,:lateral_side,"off"),goal_switch_threshold=get(cfg,:goal_switch_threshold,2),shared_stores=get(cfg,:stores,"personal")=="shared",regrowth_days=Int(get(cfg,:regrowth_days,1)),regrowth_capacity=Int(get(cfg,:regrowth_capacity,0)),skyline_mode=get(cfg,:skyline,"off"),reposition=get(cfg,:reposition,"off")=="on",selection_trails=get(cfg,:selection_trails,"off")=="on",bundle_credit=get(cfg,:bundle_credit,"off")=="on",experience_bundles=get(cfg,:experience_bundles,"off")=="on",exploration_horizon=get(cfg,:exploration_horizon,"off")=="on",movement_inertia=get(cfg,:movement_inertia,"off")=="on",body_field=get(cfg,:body_field,"off")=="on",relation_field=get(cfg,:relation_field,"off")=="on",orientation=get(cfg,:orientation,"off")=="on",basic_loop=true,landmark_routes=true,
    harvest_sleep=enabled,model_field=enabled,model_review=enabled,model_relearn=enabled,
    renewable_food=cfg.food=="renewable",hazard_mode=cfg.hazards!="off",continuous_safety=get(cfg,:safety_methods,"legacy")=="continuous",dynamic_hazard_mode=cfg.hazards in ("territorial","mixed") ? cfg.hazards : "off",ground_mode=get(cfg,:ground,"flat"),ground_wear=get(cfg,:ground_wear,"off")=="on",ground_perception=get(cfg,:ground_perception,"off")=="on",ground_continuity=get(cfg,:ground_continuity,"off")=="on",food_body=get(cfg,:food_body,"off")=="on",running=get(cfg,:running,"off")=="on",climbing=get(cfg,:climbing,"off")=="on",low_obstacles=get(cfg,:low_obstacles,"off")=="on",dropping=get(cfg,:dropping,"off")=="on",social_response=get(cfg,:social_response,"legacy")=="experience",general_sleep=get(cfg,:general_sleep,"off") in ("review","apply"),sleep_actions=get(cfg,:general_sleep,"off")=="apply",sleep_retention=get(cfg,:sleep_retention,"recent")=="strata",sleep_maintenance=get(cfg,:sleep_maintenance,"off")=="on")
summary=D("mb_map"=>r["mb_map"],"body_purpose"=>r["body_purpose"],"observed_cues"=>r["observed_cues"],"repetition_pressure"=>r["repetition_pressure"],"parent_breadth"=>r["parent_breadth"],"shared_storage"=>r["shared_storage"],"skyline"=>r["skyline"],"reposition"=>r["reposition"],"name"=>"LW-Julia integrated experiment v1","config"=>cfg,"ended_us"=>r["ended_us"],
    "food"=>D("shared"=>r["shared_stock"],"initial"=>r["initial_food"],"added"=>r["replenished_food"],"ground"=>r["ground"],"consumed"=>r["consumed"]),
    "selection_trails"=>r["selection_trails"],"experience_bundles"=>r["experience_bundles"],"exploration_horizon"=>r["exploration_horizon"],"movement_inertia"=>r["movement_inertia"],"body_field"=>r["body_field"],"relation_field"=>r["relation_field"],"orientation"=>r["orientation"],"safety_methods"=>r["safety_methods"],"world_hazards"=>r["world_hazards"],"food_body"=>r["food_body"],"ground_continuity"=>r["ground_continuity"],"ground_perception"=>r["ground_perception"],"ground_wear"=>r["ground_wear"],"sleep_action_models"=>r["sleep_action_models"],"general_sleep"=>r["general_sleep"],"social_response"=>r["social_response"],"dropped_cargo"=>r["dropped_cargo"],"climbing"=>r["climbing"],"running"=>r["running"],"ground_effects"=>r["ground_effects"],"safety"=>r["safety"],"agents"=>D())
for a in IDS
    s=r["final_agents"][a];h=s["harvest"]
    summary["agents"][a]=D("position"=>s["position"],"body"=>s["body"],"inventory"=>s["inventory"],
        "stock"=>s["personal_stock"],"distance"=>s["distance"],"operations"=>sum(values(r["counts"][a])),
        "night_statuses"=>[n["sleep"][a]["sleep"]["cycle"]["status"] for n in r["daily"]],
        "model_ref"=>h===nothing || h["model"]===nothing ? nothing : h["model"]["model_ref"],
        "replacement_used"=>h===nothing ? false : get(h,"replacement_used",false),"model_field"=>s["model_field"])
end
haskey(r,"digestion") && (summary["digestion"]=r["digestion"])
return r,summary
end
